(()=>{const ship=document.querySelector('.event-ship'),section=document.querySelector('.esc-events');if(!ship)return;const reduce=matchMedia('(prefers-reduced-motion:reduce)');let frame=0;function draw(){frame=0;if(reduce.matches||document.hidden){ship.style.transform='';return}const p=Math.max(0,Math.min(1,scrollY/(section.offsetHeight-innerHeight)));ship.style.transform=`translate3d(${Math.sin(p*Math.PI)*innerWidth*.13}px,${-p*80}px,0) rotate(${Math.sin(p*Math.PI*4)*3}deg)`}function schedule(){if(!frame)frame=requestAnimationFrame(draw)}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule,{passive:true});reduce.addEventListener('change',schedule);draw()})();
